"use client";

import { useEffect, useState } from "react";
import type { LocationSummary } from "@/features/locations/repository";
import type { AskResult, TraceStep } from "./ask";
import { describeStep } from "./trace-text";
import recorded from "./replays.json";

type Replay = { question: string; recordedAt: string; result: AskResult };
// Generated by scripts/record-replays.mts from the real local model; never hand-edited.
const replays = recorded as Replay[];

type Run =
  | { status: "thinking"; question: string }
  | { status: "error"; question: string; error: string }
  | { status: "done"; question: string; result: AskResult; recordedAt?: string };

type AskPanelProps = {
  live: boolean; // true only when the server has AI_MODE=local
  onResult: (locations: LocationSummary[] | null) => void;
  suggestions: string[]; // follow the selected place or character
  onSaveResults: (name: string, slugs: string[]) => void;
};

const recordedQuestions = new Set(replays.map((r) => r.question));

export function AskPanel({ live, onResult, suggestions, onSaveResults }: AskPanelProps) {
  const [question, setQuestion] = useState("");
  const [savedRun, setSavedRun] = useState<Run | null>(null); // the run whose results were saved, to show "Saved"
  const [run, setRun] = useState<Run | null>(null);
  const [shown, setShown] = useState(0); // how many trace steps are revealed

  const steps = run?.status === "done" ? run.result.trace : [];
  const finished = run?.status === "done" && shown >= steps.length;

  // Reveal the trace one step at a time. A replay waits each step's recorded duration, so it plays at real speed.
  useEffect(() => {
    if (run?.status !== "done") return;
    const { trace } = run.result;
    // No matches: keep every pin visible instead of emptying the map.
    if (shown >= trace.length) return onResult(run.result.locations.length ? run.result.locations : null);
    const delay = run.recordedAt ? Math.min(trace[shown].ms, 2500) : 200;
    const timer = setTimeout(() => setShown((n) => n + 1), delay);
    return () => clearTimeout(timer);
  }, [run, shown, onResult]);

  async function ask(q: string) {
    setShown(0);
    onResult(null);

    if (!live) {
      const replay = replays.find((r) => r.question === q);
      if (replay) setRun({ status: "done", question: q, result: replay.result, recordedAt: replay.recordedAt });
      return;
    }

    setRun({ status: "thinking", question: q });
    try {
      const res = await fetch("/api/ai/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question: q }),
      });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error ?? `HTTP ${res.status}`);
      setRun({ status: "done", question: q, result: body });
    } catch (error) {
      setRun({ status: "error", question: q, error: error instanceof Error ? error.message : "Request failed" });
    }
  }

  const busy = run?.status === "thinking" || (run?.status === "done" && !finished);

  return (
    <section aria-labelledby="ask-heading" className="border-b border-border pb-5">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h2 id="ask-heading" className="text-sm font-semibold">
          Ask AI
        </h2>
        <span
          className={`rounded-full border px-2.5 py-0.5 font-mono text-[10px] uppercase tracking-wider ${
            live ? "border-accent/50 text-accent" : "border-highlight/50 text-highlight"
          }`}
        >
          {live ? "Live · local model" : "Recorded demo · no live inference"}
        </span>
      </div>

      {live && (
        <form
          className="mt-3 flex gap-2"
          onSubmit={(e) => {
            e.preventDefault();
            if (question.trim()) ask(question.trim());
          }}
        >
          <input
            type="text"
            aria-label="Ask a question about Leonida"
            placeholder="Ask about Leonida…"
            maxLength={300}
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            className="min-h-9 min-w-0 flex-1 rounded-md border border-border bg-background/80 px-3 text-sm placeholder:text-muted"
          />
          <button
            type="submit"
            disabled={busy}
            className="min-h-9 rounded-md bg-accent px-3 text-sm font-medium text-background disabled:opacity-50"
          >
            Ask
          </button>
        </form>
      )}

      {/* Public mode can only offer questions that have a real recording. */}
      <div role="group" aria-label="Suggested questions" className="mt-3 flex flex-wrap gap-2">
        {suggestions
          .filter((q) => live || recordedQuestions.has(q))
          .slice(0, 5)
          .map((q) => (
          <button
            key={q}
            type="button"
            disabled={busy}
            onClick={() => ask(q)}
            className="min-h-8 rounded-full border border-border bg-surface/70 px-3 text-left text-xs text-foreground transition-colors hover:border-accent hover:text-accent disabled:opacity-50"
          >
            {q}
          </button>
        ))}
      </div>

      <div aria-live="polite" className="mt-4 text-sm">
        {run?.status === "thinking" && <p className="text-muted">Thinking… the first call can take ~10 s while the model loads.</p>}
        {run?.status === "error" && <p className="text-highlight">{run.error}</p>}
        {run?.status === "done" && !finished && <p className="text-muted">Running…</p>}
        {finished && (
          <>
            <p className="leading-relaxed">{run.result.answer}</p>
            <p className="mt-2 font-mono text-[10px] text-muted">
              {run.recordedAt
                ? `Recorded ${new Date(run.recordedAt).toLocaleDateString()} with ${run.result.model}, replayed at recorded speed.`
                : `Live answer from ${run.result.model} on this machine.`}
            </p>
            {run.result.locations.length > 0 && (
              <button
                type="button"
                disabled={savedRun === run}
                onClick={() => {
                  onSaveResults(run.question, run.result.locations.map((loc) => loc.slug));
                  setSavedRun(run);
                }}
                className="mt-3 rounded-full border border-violet/60 px-3 py-1 text-xs text-violet hover:bg-violet/10 disabled:border-border disabled:text-muted"
              >
                {savedRun === run ? "Saved to Collections" : `Save ${run.result.locations.length} places as a collection`}
              </button>
            )}
          </>
        )}
      </div>

      {run?.status === "done" && <ExecutionTrace steps={steps.slice(0, shown)} complete={finished} />}
    </section>
  );
}

// The Execution Inspector: what the model asked for, what the server checked and ran, and how long each step took.
function ExecutionTrace({ steps, complete }: { steps: TraceStep[]; complete: boolean }) {
  const [technical, setTechnical] = useState(false);
  const totalMs = steps.reduce((sum, step) => sum + step.ms, 0);
  const lookups = steps.filter((step) => step.kind === "tool").length;
  return (
    <div className="mt-4 rounded-xl border border-border bg-background/40 p-3">
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-xs font-semibold">How the AI answered</h3>
        <button
          type="button"
          aria-expanded={technical}
          onClick={() => setTechnical(!technical)}
          className="text-[11px] text-accent underline underline-offset-2"
        >
          {technical ? "Hide technical details" : "Technical details"}
        </button>
      </div>
      <ol className="mt-3 space-y-3">
        {steps.map((step, i) => {
          const text = describeStep(step);
          return (
            <li key={i} className="flex gap-2.5 text-xs">
              <span
                aria-hidden
                className={`mt-0.5 flex size-4 shrink-0 items-center justify-center rounded-full border text-[9px] ${
                  text.ok ? "border-accent/60 text-accent" : "border-highlight/60 text-highlight"
                }`}
              >
                {text.ok ? "✓" : "✕"}
              </span>
              <div className="min-w-0 flex-1">
                <div className="flex justify-between gap-2">
                  <span className="font-medium text-foreground">
                    {text.title}
                    {!text.ok && <span className="sr-only"> (failed)</span>}
                  </span>
                  <span className="shrink-0 text-muted">{formatMs(step.ms)}</span>
                </div>
                <p className="mt-0.5 text-muted">{text.detail}</p>
                {technical && (
                  <p className="mt-1 break-words font-mono text-[10px] text-muted/80">
                    {step.kind === "model"
                      ? step.toolCalls.length
                        ? `model → ${step.toolCalls.map((c) => `${c.name}(${JSON.stringify(c.arguments)})`).join(", ")}`
                        : "model → final answer"
                      : step.error
                        ? `${step.name}(${JSON.stringify(step.arguments)}) → refused: ${step.error}`
                        : `${step.name}(${JSON.stringify(step.arguments)}) → ${step.slugs?.join(", ") || "[]"}`}
                  </p>
                )}
              </div>
            </li>
          );
        })}
      </ol>
      {complete && (
        <p className="mt-3 border-t border-border pt-2 text-[11px] text-muted">
          {formatMs(totalMs)} · {lookups} database {lookups === 1 ? "lookup" : "lookups"} · read-only
          {technical && <span className="font-mono"> · {steps.length} trace steps</span>}
        </p>
      )}
    </div>
  );
}

const formatMs = (ms: number) => (ms < 1000 ? `${ms} ms` : `${(ms / 1000).toFixed(1)} s`);
